static std::string utf8(NSString *s){return s?s.UTF8String:"";}
static NSString *text(const std::string &s){return [NSString stringWithUTF8String:s.c_str()];}
static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static int protocolFd=-1;
static void result(id value){NSError *error=nil;NSData *data=[NSJSONSerialization dataWithJSONObject:value options:0 error:&error];require(data!=nil,"Cannot encode plugin response");FILE *out=fdopen(dup(protocolFd),"w");require(out!=nullptr,"Cannot open plugin response");auto written=fwrite(data.bytes,1,data.length,out);fclose(out);require(written==data.length,"Cannot write plugin response");}
static bool effect(const ClassInfo &c){return c.category()==kVstAudioEffectClass && c.subCategoriesString().find("Instrument")==std::string::npos;}
static std::vector<std::string> paths(NSDictionary *request){auto list=Module::getModulePaths();for(NSString *folder in request[@"folders"]){NSString *expanded=folder.stringByExpandingTildeInPath;NSDirectoryEnumerator *items=[[NSFileManager defaultManager] enumeratorAtPath:expanded];for(NSString *item in items){if([item.pathExtension.lowercaseString isEqualToString:@"vst3"]){list.push_back(utf8([expanded stringByAppendingPathComponent:item]));[items skipDescendants];}}}std::sort(list.begin(),list.end());list.erase(std::unique(list.begin(),list.end()),list.end());return list;}
static void scan(NSDictionary *request){NSMutableArray *values=[NSMutableArray array];for(const auto &path:paths(request)){std::string error;auto module=Module::create(path,error);if(!module)continue;for(const auto &c:module->getFactory().classInfos())if(effect(c)){auto id="vst3:"+c.ID().toString()+":"+path;[values addObject:@{@"id":text(id),@"name":text(c.name()),@"manufacturer":text(c.vendor()),@"format":@"VST3"}];}}result(values);}
struct Loaded {
 IPtr<HostApplication> host;Module::Ptr module;std::unique_ptr<PlugProvider> provider;IPtr<IComponent> component;IPtr<IEditController> controller;IPtr<IAudioProcessor> processor;bool active=false;
 explicit Loaded(NSString *identifier){std::string id=utf8(identifier);require(id.size()>39&&id.rfind("vst3:",0)==0&&id[37]==':',"Invalid VST3 identifier");std::string error;module=Module::create(id.substr(38),error);require(module!=nullptr,error.c_str());auto uid=VST3::UID::fromString(id.substr(5,32));require(bool(uid),"Invalid VST3 class");host=owned(new HostApplication);PluginContextFactory::instance().setPluginContext(host);module->getFactory().setHostContext(host);
  for(const auto &c:module->getFactory().classInfos())if(c.ID()==*uid&&effect(c)){provider=std::make_unique<PlugProvider>(module->getFactory(),c,true);break;}require(provider&&provider->initialize(),"Cannot instantiate VST3 effect");component=provider->getComponentPtr();controller=provider->getControllerPtr();processor=FUnknownPtr<IAudioProcessor>(component);require(component&&controller&&processor,"VST3 effect needs an audio processor and controller");}
 ~Loaded(){if(active){processor->setProcessing(false);component->setActive(false);}processor=nullptr;controller=nullptr;component=nullptr;provider.reset();module.reset();PluginContextFactory::instance().setPluginContext(nullptr);}
 void restore(NSString *value){if(!value.length)return;require(value.length<8'000'000,"VST3 state is too large");NSData *data=[[NSData alloc]initWithBase64EncodedString:value options:0];require(data!=nil,"Invalid VST3 state");NSDictionary *state=[NSJSONSerialization JSONObjectWithData:data options:0 error:nil];require([state isKindOfClass:NSDictionary.class],"Invalid VST3 state");for(NSString *key in @[@"component",@"controller"]){NSData *bytes=[[NSData alloc]initWithBase64EncodedString:state[key] options:0];require(bytes!=nil,"Invalid VST3 state data");MemoryStream stream((void *)bytes.bytes,bytes.length);if([key isEqualToString:@"component"]){require(component->setState(&stream)==kResultOk,"Cannot restore VST3 component");stream.seek(0,IBStream::kIBSeekSet,nullptr);controller->setComponentState(&stream);}else controller->setState(&stream);}}
 NSString *state(){MemoryStream a,b;require(component->getState(&a)==kResultOk,"Cannot save VST3 component");controller->getState(&b);NSData *ca=[NSData dataWithBytes:a.getData() length:a.getSize()],*cb=[NSData dataWithBytes:b.getData() length:b.getSize()];NSData *json=[NSJSONSerialization dataWithJSONObject:@{@"component":[ca base64EncodedStringWithOptions:0],@"controller":[cb base64EncodedStringWithOptions:0]} options:0 error:nil];return [json base64EncodedStringWithOptions:0];}
 NSMutableArray *parameters(){NSMutableArray *values=[NSMutableArray array];for(int32 i=0;i<controller->getParameterCount();i++){ParameterInfo p{};if(controller->getParameterInfo(i,p)!=kResultOk)continue;auto minimum=controller->normalizedParamToPlain(p.id,0),maximum=controller->normalizedParamToPlain(p.id,1),value=controller->normalizedParamToPlain(p.id,controller->getParamNormalized(p.id));bool plain=std::isfinite(minimum)&&std::isfinite(maximum)&&minimum<maximum&&std::isfinite(value);NSString *name=[[NSString alloc]initWithCharacters:(const unichar *)p.title length:std::char_traits<char16_t>::length((const char16_t *)p.title)];NSString *unit=plain?[[NSString alloc]initWithCharacters:(const unichar *)p.units length:std::char_traits<char16_t>::length((const char16_t *)p.units)]:@"normalized";[values addObject:@{@"address":[NSString stringWithFormat:@"%u",p.id],@"name":name?:@"Parameter",@"min":@(plain?minimum:0),@"max":@(plain?maximum:1),@"value":@(plain?value:controller->getParamNormalized(p.id)),@"unit":unit?:@""}];}return values;}
 void changes(NSDictionary *params,ParameterChanges &changes){changes.setMaxParameters(controller->getParameterCount());for(NSString *key in params){long long address=key.longLongValue;require(address>=0&&address<=UINT32_MAX,"Invalid VST3 parameter");double plain=[params[key] doubleValue];require(std::isfinite(plain),"Invalid VST3 parameter value");ParamID id=(ParamID)address;bool found=false;ParameterInfo p{};for(int32 i=0;i<controller->getParameterCount();i++)if(controller->getParameterInfo(i,p)==kResultOk&&p.id==id){found=true;break;}require(found,"Unknown VST3 parameter");auto min=controller->normalizedParamToPlain(id,0),max=controller->normalizedParamToPlain(id,1);bool mapped=std::isfinite(min)&&std::isfinite(max)&&min<max;double normalized=mapped?controller->plainParamToNormalized(id,plain):plain;require(std::isfinite(normalized)&&normalized>=0&&normalized<=1,"VST3 parameter out of bounds");controller->setParamNormalized(id,normalized);int32 queueIndex=0,pointIndex=0;auto queue=changes.addParameterData(id,queueIndex);require(queue!=nullptr,"Cannot queue VST3 parameter");queue->addPoint(0,normalized,pointIndex);}}
};
static void run(NSString *operation,NSDictionary *request){if([operation isEqualToString:@"plugin-scan"]){scan(request);return;}Loaded plugin(request[@"id"]);plugin.restore(request[@"state"]);ParameterChanges changes;plugin.changes(request[@"parameters"]?:@{},changes);
 if([operation isEqualToString:@"plugin-info"]){result(@{@"parameters":plugin.parameters(),@"state":plugin.state(),@"latency":@0});return;}
 require([operation isEqualToString:@"plugin-render"],"Invalid VST3 operation");double offset=[request[@"offset"] doubleValue],duration=[request[@"duration"] doubleValue];require(std::isfinite(offset)&&offset>=0&&std::isfinite(duration)&&duration>0&&duration<=120,"Invalid VST3 render window");NSString *path=request[@"path"],*output=request[@"output"];require(path.length&&output.length&&![[NSFileManager defaultManager]fileExistsAtPath:output],"Invalid VST3 files");NSError *error=nil;AVAudioFile *file=[[AVAudioFile alloc]initForReading:[NSURL fileURLWithPath:path] error:&error];require(file!=nil,"Cannot read VST3 source");AVAudioFormat *format=file.processingFormat;double rate=format.sampleRate;uint32 originalChannels=format.channelCount;require(originalChannels>0&&originalChannels<=2,"VST3 source must be mono or stereo");AVAudioFramePosition count=llround(duration*rate),start=llround(offset*rate);require(start+count<=file.length,"VST3 source bounds");AVAudioPCMBuffer *input=[[AVAudioPCMBuffer alloc]initWithPCMFormat:format frameCapacity:(AVAudioFrameCount)count];file.framePosition=start;require([file readIntoBuffer:input frameCount:(AVAudioFrameCount)count error:&error],"Cannot decode VST3 source");
 auto arrangement=originalChannels==1?SpeakerArr::kMono:SpeakerArr::kStereo;int32 channels=originalChannels;if(plugin.processor->setBusArrangements(&arrangement,1,&arrangement,1)!=kResultOk){arrangement=SpeakerArr::kStereo;channels=2;require(plugin.processor->setBusArrangements(&arrangement,1,&arrangement,1)==kResultOk,"VST3 effect does not support mono/stereo");}
 for(auto direction:{kInput,kOutput})for(int32 bus=0;bus<plugin.component->getBusCount(kAudio,direction);bus++)plugin.component->activateBus(kAudio,direction,bus,bus==0);require(plugin.processor->canProcessSampleSize(kSample32)==kResultOk,"VST3 effect needs float32 processing");ProcessSetup setup{kOffline,kSample32,4096,rate};require(plugin.processor->setupProcessing(setup)==kResultOk&&plugin.component->setActive(true)==kResultOk,"Cannot configure VST3 effect");plugin.active=true;require(plugin.processor->setProcessing(true)==kResultOk,"Cannot start VST3 effect");bool bypass=[request[@"bypass"] boolValue];uint32 delay=0;
 NSMutableDictionary *settings=[format.settings mutableCopy];settings[AVLinearPCMIsNonInterleaved]=@NO;AVAudioFile *writer=[[AVAudioFile alloc]initForWriting:[NSURL fileURLWithPath:output] settings:settings commonFormat:AVAudioPCMFormatFloat32 interleaved:NO error:&error];require(writer!=nil,"Cannot create VST3 output");
 std::vector<std::vector<float>> ins(channels,std::vector<float>(4096)),outs(channels,std::vector<float>(4096));std::vector<float *>inPointers(channels),outPointers(channels);for(int32 ch=0;ch<channels;ch++){inPointers[ch]=ins[ch].data();outPointers[ch]=outs[ch].data();}AudioBusBuffers inBus,outBus;inBus.numChannels=channels;inBus.channelBuffers32=inPointers.data();outBus.numChannels=channels;outBus.channelBuffers32=outPointers.data();
 ProcessContext context{};context.sampleRate=rate;context.tempo=120;context.timeSigNumerator=4;context.timeSigDenominator=4;context.state=ProcessContext::kPlaying|ProcessContext::kTempoValid|ProcessContext::kTimeSigValid;ProcessData flush{};flush.processMode=kOffline;flush.symbolicSampleSize=kSample32;flush.numInputs=1;flush.numOutputs=1;flush.inputs=&inBus;flush.outputs=&outBus;flush.inputParameterChanges=&changes;flush.processContext=&context;require(plugin.processor->process(flush)==kResultOk,"VST3 parameter flush failed");delay=bypass?0:plugin.processor->getLatencySamples();require(delay<=rate*10,"VST3 latency exceeds ten seconds");AVAudioFramePosition rendered=0;bool first=false;NSDate *limit=[NSDate dateWithTimeIntervalSinceNow:60];
 while(rendered<count+delay){require(limit.timeIntervalSinceNow>0,"VST3 render timed out");int32 frames=(int32)std::min<AVAudioFramePosition>(4096,count+delay-rendered);for(int32 ch=0;ch<channels;ch++)for(int32 i=0;i<frames;i++){ins[ch][i]=rendered+i<count?input.floatChannelData[std::min<uint32>(ch,originalChannels-1)][rendered+i]:0;outs[ch][i]=0;}context.projectTimeSamples=rendered;ProcessData data{};data.processMode=kOffline;data.symbolicSampleSize=kSample32;data.numSamples=frames;data.numInputs=1;data.numOutputs=1;data.inputs=&inBus;data.outputs=&outBus;data.inputParameterChanges=first?&changes:nullptr;data.processContext=&context;if(bypass){for(int32 ch=0;ch<channels;ch++)std::copy_n(ins[ch].data(),frames,outs[ch].data());}else require(plugin.processor->process(data)==kResultOk,"VST3 DSP failed");require(bypass||plugin.processor->getLatencySamples()==delay,"VST3 latency changed during rendering");first=false;int32 skip=(int32)std::max<AVAudioFramePosition>(0,std::min<AVAudioFramePosition>(frames,delay-rendered)),kept=frames-skip;if(kept>0){AVAudioPCMBuffer *block=[[AVAudioPCMBuffer alloc]initWithPCMFormat:format frameCapacity:kept];block.frameLength=kept;for(uint32 ch=0;ch<originalChannels;ch++)for(int32 i=0;i<kept;i++){float v=originalChannels==1&&channels==2?(outs[0][i+skip]+outs[1][i+skip])*.5:outs[ch][i+skip];require(std::isfinite(v),"VST3 produced non-finite samples");block.floatChannelData[ch][i]=v;}require([writer writeFromBuffer:block error:&error],"Cannot write VST3 audio");}rendered+=frames;}
 result(@{@"path":output,@"parameters":plugin.parameters(),@"state":plugin.state(),@"latency":@(delay/rate),@"frames":@(count),@"sampleRate":@(rate)});
}
int main(int argc,char **argv){@autoreleasepool{try{protocolFd=dup(STDOUT_FILENO);dup2(STDERR_FILENO,STDOUT_FILENO);require(argc>=3,"Expected VST3 operation and JSON file");alarm(65);NSString *operation=text(argv[1]),*arg=text(argv[2]);NSData *data=[arg hasPrefix:@"{"]?[arg dataUsingEncoding:NSUTF8StringEncoding]:[NSData dataWithContentsOfFile:arg];require(data!=nil,"Cannot read VST3 request");NSDictionary *request=[NSJSONSerialization JSONObjectWithData:data options:0 error:nil];require([request isKindOfClass:NSDictionary.class],"Invalid VST3 request");run(operation,request);return 0;}catch(const std::exception &error){std::cerr<<error.what()<<std::endl;return 1;}}}
